import{seed,slots,today,day,available,reserve,pay,cancel,assess,expire}from'./model.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=seed(),role='student',page='overview',filter='all',instructor='i1',draft={date:day(1),time:'',instructor:'i1',vehicle:'v1'};
try{const saved=JSON.parse(sessionStorage.getItem('drivex-v1'));if(saved?.version===1&&saved.day===today())state=saved.state}catch{}
function save(){try{sessionStorage.setItem('drivex-v1',JSON.stringify({version:1,day:today(),state}))}catch{toast('Changes remain available until this page is refreshed.')}}
const money=v=>'₹'+Number(v).toLocaleString('en-IN'),date=d=>new Date(d+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'}),weekday=d=>new Date(d+'T12:00:00').toLocaleDateString('en-IN',{weekday:'long'}),name=id=>esc(state.instructors.find(i=>i.id===id)?.name||'Instructor'),vehicle=id=>state.vehicles.find(v=>v.id===id),tag=s=>`<span class="tag ${esc(s)}">${esc(s)}</span>`;
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16 M8 14h2 M14 14h2',car:'M5 8l2-4h10l2 4 M3 9h18v9H3z M6 18v3 M18 18v3 M6 13h2 M16 13h2',chart:'M4 4v16h17 M8 15v-4 M13 15V7 M18 15V3',wallet:'M3 6h17v14H3z M3 6V3h14 M15 11h6v5h-6z',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 21v-3a8 6 0 0 1 16 0v3',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 6v6l4 2',plus:'M12 4v16 M4 12h16',book:'M3 4h8l1 2 1-2h8v16h-8l-1 1-1-1H3z M12 6v15',check:'M5 12l4 4L19 6',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 11v6 M12 7v1'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
const navs={student:[['overview','grid','Overview'],['book','calendar','Book a lesson'],['lessons','car','My lessons'],['progress','chart','My progress'],['payments','wallet','Payments']],instructor:[['overview','grid','Overview'],['lessons','calendar','My schedule'],['progress','book','Assessments']],admin:[['overview','grid','Overview'],['lessons','calendar','All bookings'],['team','user','Instructors'],['fleet','car','Vehicles'],['payments','wallet','Payments']]};
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000)}
function list(){expire(state);return state.bookings.filter(b=>role==='instructor'?b.instructor===instructor&&['confirmed','completed'].includes(b.status):true).sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time))}
function navigate(p){page=p;filter='all';render();window.scrollTo(0,0)}
function stat(label,value,note,ico,good=false){return`<div class="stat"><div class="stat-head">${label}${icon(ico)}</div><div class="number">${value}</div><div class="stat-note ${good?'good':''}">${note}</div></div>`}
function render(){expire(state);const title=navs[role].find(x=>x[0]===page)?.[2]||'Overview';$('#app').innerHTML=`<div class="shell"><aside class="side"><div class="brand"><div class="brandmark">D</div>Drive<span>X</span></div><small>${role==='student'?'Your driving journey':'School workspace'}</small><nav class="nav" aria-label="Main navigation">${navs[role].map(([id,i,label])=>`<button data-nav="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(i)}${label}</button>`).join('')}</nav><div class="side-bottom"><div class="side-note"><b>Confidence comes with practice.</b>One lesson closer to the open road.</div><div class="side-foot">DriveX Driving School<br><br>Bengaluru, India</div></div></aside><div><header class="topbar"><div class="crumb">Workspace <b>/ &nbsp;${title}</b></div><div class="persona"><label class="sr-label"><select id="role" aria-label="Preview as role"><option value="student" ${role==='student'?'selected':''}>Student preview</option><option value="instructor" ${role==='instructor'?'selected':''}>Instructor preview</option><option value="admin" ${role==='admin'?'selected':''}>Admin preview</option></select></label><div class="avatar">${role==='student'?'JE':role==='admin'?'AD':'AM'}</div><div class="meta-name">${role==='student'?'Jerrin':role==='admin'?'School admin':name(instructor)}<small>${role[0].toUpperCase()+role.slice(1)}</small></div></div></header><div class="demo-banner"><span>REVIEW DEMO · Sample data & simulated payments · Changes stay in this tab</span><button id="reset">Reset demo</button></div><main class="content">${page==='overview'?overview():page==='book'?booking():page==='lessons'?lessons():page==='progress'?progress():page==='team'?resources('team'):page==='fleet'?resources('fleet'):payments()}<footer class="footer"><span>DriveX · Make every lesson count.</span><span>All lesson times: India Standard Time</span></footer></main></div></div>`;bind()}
function intro(title,sub,action=''){return`<div class="intro"><div><div class="eyebrow">${role==='student'?'Learner workspace':role==='admin'?'School management':'Instructor workspace'}</div><h1>${title}</h1><p class="sub">${sub}</p></div>${action}</div>`}
function overview(){const all=list(),done=all.filter(b=>b.status==='completed'),up=all.filter(b=>b.status==='confirmed').sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)),avg=done.length?(done.reduce((s,b)=>s+b.score,0)/done.length).toFixed(1):'—',total=state.payments.filter(p=>p.status==='paid').reduce((s,p)=>s+p.amount,0);return`${intro(role==='student'?'Your next chapter starts here.':role==='admin'?'Your school, at a glance.':'Ready for the road?',role==='student'?'Welcome back, Jerrin. Let’s keep your momentum going.':role==='admin'?'Keep your lessons, people, and payments moving.':'Your lessons and student feedback, in one place.',role==='student'?`<button class="primary" data-nav="book">${icon('plus')} Book a lesson</button>`:'')}<div class="stats">${stat(role==='admin'?'Total bookings':'Lessons completed',role==='admin'?all.length:done.length,role==='student'?'of your 10-lesson goal':'Across your schedule','car')}${stat('Upcoming lessons',up.length,'Confirmed & paid','calendar')}${stat(role==='admin'?'Active instructors':'Average score',role==='admin'?state.instructors.length:`${avg} <small>/ 10</small>`,role==='admin'?'Available for bookings':'From instructor assessments','chart',true)}${stat(role==='admin'?'Demo revenue':role==='instructor'?'Students taught':'Learning hours',role==='admin'?money(total):role==='instructor'?new Set(done.map(b=>b.student)).size:`${done.length} <small>hrs</small>`,role==='admin'?'Paid, excluding demo refunds':role==='instructor'?'With completed lessons':'Time well invested','clock')}</div><div class="grid"><section class="panel panel-pad"><div class="panel-head"><h2>${role==='admin'?'Next scheduled lesson':'Your next lesson'}</h2><button class="link" data-nav="lessons">View schedule</button></div>${up[0]?hero(up[0]):`<div class="empty"><b>Your calendar is clear</b>${role==='student'?'Book a lesson to keep practising.':'New confirmed lessons will appear here.'}</div>`}<div class="hint">${icon('info')}<span>${role==='student'?'Bring your learner’s licence and arrive 10 minutes early. Comfortable, flat shoes make all the difference.':'Only confirmed, paid bookings appear in the upcoming schedule.'}</span></div></section><section class="panel panel-pad"><div class="panel-head"><h2>${role==='admin'?'School resources':role==='instructor'?'Student lesson progress':'Your learning progress'}</h2>${tag('on track')}</div>${role==='admin'?`<div class="progress-layout"><div class="ring" style="--pct:100"><div class="ring-inner"><b>${state.vehicles.length}</b><small>vehicles</small></div></div><div><h3>Ready for lessons</h3><p class="sub">${state.instructors.length} instructors<br>${state.vehicles.length} training vehicles</p></div></div><button class="secondary full" data-nav="fleet">Manage vehicles</button>`:`<div class="progress-layout"><div class="ring" style="--pct:${Math.min(done.length*10,100)}"><div class="ring-inner"><b>${Math.min(done.length*10,100)}%</b><small>of lesson goal</small></div></div><div><h3>Building confidence</h3><p class="sub">${done.length} of 10 lessons completed.<br>Keep showing up for yourself.</p></div></div><div class="milestones"><div class="milestone"><span class="check">${done.length?'✓':'1'}</span>First lesson ${done.length?'completed':'ahead'}</div><div class="milestone"><span class="check">${done.length>=5?'✓':'2'}</span><span class="${done.length<5?'muted':''}">Halfway: 5 lessons</span></div><div class="milestone"><span class="check">${done.length>=10?'✓':'3'}</span><span class="muted">Goal: 10 lessons</span></div></div>`}</section></div><section class="panel section-gap"><div class="panel-head table-title"><h2>Recent lessons</h2><button class="link" data-nav="lessons">View all lessons</button></div>${table(all.slice(0,4))}</section>`}
function hero(b){const v=vehicle(b.vehicle),i=state.instructors.find(i=>i.id===b.instructor);return`<div class="lesson-hero"><div class="hero-top"><span class="eyebrow">${weekday(b.date)} · ${date(b.date)}</span>${tag(b.status)}</div><h2>${esc(v.name)} driving lesson</h2><p class="sub">${esc(v.transmission)} · 60-minute practical lesson</p><div class="hero-time">${icon('clock')}${b.time} – ${String(Number(b.time.slice(0,2))+1).padStart(2,'0')}:00 &nbsp; IST</div><div class="hero-foot"><div class="person"><div class="avatar">${esc(i.initials)}</div><div>${name(b.instructor)}<small>Your driving instructor</small></div></div><button class="primary lime" data-detail="${b.id}">Lesson details</button></div></div>`}
function table(items){if(!items.length)return'<div class="empty"><b>No lessons here yet</b>New bookings will appear here.</div>';return`<div class="table-wrap"><table><thead><tr><th>LESSON</th><th>${role==='student'?'INSTRUCTOR':'STUDENT'}</th><th>VEHICLE</th><th>STATUS</th><th>${role==='student'?'SCORE':'ACTION'}</th></tr></thead><tbody>${items.map(b=>`<tr><td><button class="link" style="color:inherit;padding:0" data-detail="${b.id}">${date(b.date)}</button><small>${b.time} · 60 min</small></td><td>${role==='student'?name(b.instructor):esc(b.student)}<small>${role==='student'?'Driving instructor':name(b.instructor)}</small></td><td>${esc(vehicle(b.vehicle)?.name)}<small>${esc(vehicle(b.vehicle)?.transmission)}</small></td><td>${tag(b.status)}</td><td>${b.score?`<span class="score">${b.score} / 10</span>`:role==='instructor'&&b.status==='confirmed'?`<button class="link" data-assess="${b.id}">Add feedback</button>`:`<button class="link" data-detail="${b.id}">${b.status==='pending'?'Pay now':'Details'}</button>`}</td></tr>`).join('')}</tbody></table></div>`}
function booking(){return`${intro('Make time for the road.','Choose your instructor, vehicle, and a time that works for you.')}<div class="grid"><section class="panel panel-pad"><div class="panel-head"><h2>Book your next lesson</h2><span class="tag">60 minutes</span></div><form id="booking-form" class="booking-form"><label>Lesson date<input type="date" id="date" value="${draft.date}" min="${today()}" required></label><div class="form-row"><label>Instructor<select id="instructor">${state.instructors.map(i=>`<option value="${i.id}" ${draft.instructor===i.id?'selected':''}>${esc(i.name)}</option>`).join('')}</select></label><label>Training vehicle<select id="vehicle">${state.vehicles.map(v=>`<option value="${v.id}" ${draft.vehicle===v.id?'selected':''}>${esc(v.name)} · ${esc(v.transmission)}</option>`).join('')}</select></label></div><div><h3 style="margin-bottom:13px">Available times <span class="muted" style="font-size:13px;font-weight:400">· IST</span></h3><div class="slots">${slots.map(t=>{const ok=available(state,{...draft,time:t})&&new Date(draft.date+'T'+t+':00+05:30')>new Date();return`<button type="button" class="slot ${draft.time===t?'selected':''}" data-time="${t}" aria-pressed="${draft.time===t}" ${ok?'':'disabled'}>${t}</button>`}).join('')}</div><p class="sub">Unavailable times are crossed out. Every lesson lasts one hour.</p></div><p id="book-error" class="error" role="alert"></p></form></section><aside class="panel panel-pad" style="align-self:start"><h2>Your lesson summary</h2><div class="summary-line"><span class="muted">Date</span><b>${date(draft.date)}</b></div><div class="summary-line"><span class="muted">Time</span><b>${draft.time||'Choose a time'}</b></div><div class="summary-line"><span class="muted">Instructor</span><span>${name(draft.instructor)}</span></div><div class="summary-line"><span class="muted">Vehicle</span><span>${esc(vehicle(draft.vehicle)?.name)}</span></div><div class="summary-line"><span class="muted">Duration</span><span>60 minutes</span></div><div class="summary-line total"><span>Lesson total</span><span>₹800</span></div><button class="primary full" id="reserve" ${draft.time?'':'disabled'}>Reserve & continue</button><div class="hint">${icon('info')}<span>We’ll hold your slot for 10 minutes while you complete the demo checkout. No real charge.</span></div></aside></div>`}
function lessons(){let items=list();if(filter!=='all')items=items.filter(b=>b.status===filter);return`${intro(role==='student'?'Every lesson is a step forward.':'Your lesson schedule.',role==='student'?'Manage upcoming lessons and revisit the ones you’ve completed.':'Review bookings, lesson details, and student feedback.',role==='student'?'<button class="primary" data-nav="book">Book a lesson</button>':'')}${role==='instructor'?`<label style="max-width:280px;margin-bottom:20px">Instructor<select id="assigned">${state.instructors.map(i=>`<option value="${i.id}" ${instructor===i.id?'selected':''}>${esc(i.name)}</option>`).join('')}</select></label>`:''}<div class="filters">${['all','confirmed','completed','pending','cancelled','expired'].map(f=>`<button data-filter="${f}" class="${f===filter?'active':''}">${f==='all'?'All lessons':f[0].toUpperCase()+f.slice(1)}</button>`).join('')}</div><section class="panel">${table(items)}</section>${role==='instructor'?'<p class="sub">Feedback opens after a lesson ends. To test the full flow, use “Add finished demo lesson” below.</p><button class="secondary section-gap" id="demo-lesson">Add finished demo lesson</button>':''}`}
function progress(){const done=list().filter(b=>b.status==='completed'),avg=done.length?(done.reduce((a,b)=>a+b.score,0)/done.length).toFixed(1):'—';return`${intro(role==='student'?'Look how far you’ve come.':'Lesson assessments.','Practical feedback to make the next drive better.')}<div class="grid"><section class="panel panel-pad"><div class="panel-head"><h2>Performance over time</h2><span class="score">${avg} / 10 average</span></div><p class="sub">Scores from your completed lessons</p><div class="bars">${[...done].reverse().slice(-8).map((b,i)=>`<div class="bar-item"><div class="bar" style="height:${b.score*13}px">${b.score}</div><span>${date(b.date)}</span></div>`).join('')||'<p class="sub">Complete your first lesson to see your progress.</p>'}</div></section><section class="panel panel-pad"><h2>Keep the progress going</h2><p class="sub">Take your instructor’s feedback into your next lesson. Small improvements add up.</p><div class="summary-line"><span>Completed lessons</span><b>${done.length}</b></div><div class="summary-line"><span>Practice time</span><b>${done.length} hours</b></div>${role==='student'?'<button class="primary full section-gap" data-nav="book">Book your next lesson</button>':''}</section></div><div class="section-gap panel panel-pad"><div class="panel-head"><h2>Instructor feedback</h2><span class="muted" style="font-size:14px">${done.length} assessments</span></div><div class="card-list">${done.map(b=>`<article class="feedback"><div class="feedback-top"><h3>${date(b.date)} · ${esc(vehicle(b.vehicle)?.name)}</h3><span class="tag">${b.score} / 10</span></div><p>${esc(b.notes)}</p><div class="person"><div class="avatar">${esc(state.instructors.find(i=>i.id===b.instructor)?.initials)}</div><span>${name(b.instructor)}</span></div></article>`).join('')||'<div class="empty">Your feedback will appear after an assessed lesson.</div>'}</div></div>`}
function resources(type){const team=type==='team',items=team?state.instructors:state.vehicles;return`${intro(team?'Good teachers. Confident drivers.':'Your fleet, ready to go.',team?'Manage the people behind every successful lesson.':'Training vehicles available for student bookings.',`<button class="primary" id="add-resource" data-kind="${type}">${icon('plus')}Add ${team?'instructor':'vehicle'}</button>`)}<div class="cards">${items.map(i=>`<article class="resource"><div class="resource-icon">${icon(team?'user':'car')}</div><div class="eyebrow">${team?'Driving instructor':esc(i.transmission)}</div><h2>${esc(i.name)}</h2><p>${team?esc(i.specialty):esc(i.reg)}</p><p>${team?esc(i.phone):'60-minute lessons · ₹800'}</p><span class="tag">Available for bookings</span></article>`).join('')}</div>`}
function payments(){const ps=state.payments,paid=ps.filter(p=>p.status==='paid').reduce((a,p)=>a+p.amount,0);return`${intro('A clear view of every payment.','Demo transactions only. No money is collected or refunded.')}<div class="stats">${stat('Total paid',money(paid),'Excludes demo refunds','wallet')}${stat('Paid transactions',ps.filter(p=>p.status==='paid').length,'Successful demo checkouts','check')}${stat('Pending bookings',state.bookings.filter(b=>b.status==='pending').length,'Complete checkout in My lessons','clock')}${stat('Demo refunds',money(ps.filter(p=>p.status==='refunded').reduce((a,p)=>a+p.amount,0)),'Cancelled lessons','wallet')}</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>TRANSACTION</th><th>LESSON</th><th>AMOUNT</th><th>STATUS</th></tr></thead><tbody>${[...ps].reverse().map(p=>{const b=state.bookings.find(b=>b.id===p.booking);return`<tr><td>DX-${esc(p.id.slice(0,8).toUpperCase())}<small>Simulated transaction</small></td><td>${b?date(b.date)+' · '+b.time:'—'}<small>${b?name(b.instructor):''}</small></td><td>${money(p.amount)}</td><td>${tag(p.status)}</td></tr>`}).join('')}</tbody></table></div></section>`}
function modal(title,body){const m=$('#modal');m.innerHTML=`<div class="modal-top"><h2 id="modal-title">${title}</h2><button class="close" aria-label="Close dialog">×</button></div>${body}`;m.querySelector('.close').onclick=()=>m.close();if(!m.open)m.showModal();m.querySelector('input,select,button:not(.close)')?.focus()}
function checkout(id){const b=state.bookings.find(b=>b.id===id);modal('Complete your booking',`<p class="sub">Demo checkout · No card details needed.</p><div class="modal-body"><div class="summary-line"><span>${date(b.date)} · ${b.time} IST</span><b>₹800</b></div><p class="sub">${name(b.instructor)} · ${esc(vehicle(b.vehicle).name)}<br>Your reservation expires at ${new Date(b.expiresAt).toLocaleTimeString('en-IN',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit'})} IST.</p><p class="error" id="payment-error" role="alert"></p><button class="primary full" id="pay-success">Simulate successful payment</button><button class="secondary full" id="pay-fail">Simulate failed payment</button></div>`);$('#pay-success').onclick=()=>{try{pay(state,id);save();render();modal('You’re booked in.',`<div class="success-mark">✓</div><p class="sub">Your demo lesson is confirmed for ${date(b.date)} at ${b.time} IST. Your instructor can now see it in their schedule.</p><button class="primary full section-gap" id="view-booking">View my lessons</button>`);$('#view-booking').onclick=()=>{$('#modal').close();navigate('lessons')}}catch(e){$('#payment-error').textContent=e.message;render()}};$('#pay-fail').onclick=()=>{try{pay(state,id,false);save();render();$('#payment-error').textContent='Demo payment failed. Your slot is still held until expiry; you can try again.'}catch(e){$('#payment-error').textContent=e.message}}}
function detail(id){const b=state.bookings.find(b=>b.id===id);modal('Lesson details',`<div class="modal-body">${tag(b.status)}<div class="detail-grid"><b>${date(b.date)} · ${b.time} IST</b><p class="sub">60-minute driving lesson<br>${name(b.instructor)} · ${esc(vehicle(b.vehicle)?.name)}<br>${esc(vehicle(b.vehicle)?.reg)}<br>Student: ${esc(b.student)}</p></div>${role==='instructor'?'<p class="sub">Student contact: sample account — no real phone number</p>':''}${b.score?`<div class="feedback"><b>Performance: ${b.score}/10</b><p>${esc(b.notes)}</p></div>`:''}${['pending','confirmed'].includes(b.status)?`<div class="modal-actions">${b.status==='pending'&&role!=='instructor'?'<button class="primary" id="resume-pay">Continue checkout</button>':''}${role!=='instructor'?'<button class="danger" id="cancel-booking">Cancel lesson</button>':''}</div>`:''}</div>`);if($('#resume-pay'))$('#resume-pay').onclick=()=>checkout(id);if($('#cancel-booking'))$('#cancel-booking').onclick=()=>{modal('Cancel this lesson?',`<p class="sub">This releases the slot. Any paid demo transaction will be marked refunded.</p><div class="modal-actions"><button class="secondary" id="keep">Keep lesson</button><button class="danger" id="confirm-cancel">Cancel lesson</button></div>`);$('#keep').onclick=()=>detail(id);$('#confirm-cancel').onclick=()=>{try{cancel(state,id);save();$('#modal').close();render();toast('Lesson cancelled. The slot is available again.')}catch(e){toast(e.message)}}}}
function feedback(id){const b=state.bookings.find(b=>b.id===id);if(new Date(b.date+'T'+b.time+':00+05:30').getTime()+3600000>Date.now()){toast('Feedback opens after this lesson ends.');return}modal('Record lesson feedback',`<p class="sub">${esc(b.student)} · ${date(b.date)}</p><form id="feedback-form" class="modal-body"><label>Performance score (1–10)<input name="score" type="number" min="1" max="10" step="1" value="8" required></label><label>Lesson notes<textarea name="notes" maxlength="1500" placeholder="What went well? What should the student practise?" required></textarea></label><p class="error" role="alert" id="feedback-error"></p><button class="primary">Save assessment & complete lesson</button></form>`);$('#feedback-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{assess(state,id,instructor,Number(f.get('score')),String(f.get('notes')));save();$('#modal').close();render();toast('Feedback saved. The student can now see their assessment.')}catch(e){$('#feedback-error').textContent=e.message}}}
function addResource(type){const team=type==='team';modal(`Add ${team?'instructor':'vehicle'}`,`<form id="resource-form" class="modal-body"><label>${team?'Full name':'Vehicle model'}<input name="name" required maxlength="70" placeholder="${team?'e.g. Neha Rao':'e.g. Maruti Baleno'}"></label><label>${team?'Contact phone':'Registration number'}<input name="detail" required maxlength="30" placeholder="${team?'e.g. +91 98765 43210':'e.g. KA 01 AB 1234'}"></label>${team?'<label>Specialty<input name="extra" required maxlength="70" placeholder="e.g. Parking & city driving"></label>':'<label>Transmission<select name="extra"><option>Manual</option><option>Automatic</option></select></label>'}<p class="error" id="resource-error" role="alert"></p><button class="primary">Add ${team?'instructor':'vehicle'}</button></form>`);$('#resource-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),n=String(f.get('name')).trim(),d=String(f.get('detail')).trim(),extra=String(f.get('extra')).trim();if(!n||!d||!extra){$('#resource-error').textContent='Complete all fields.';return}if(!team&&state.vehicles.some(v=>v.reg.replace(/\s/g,'').toUpperCase()===d.replace(/\s/g,'').toUpperCase())){$('#resource-error').textContent='This registration number is already in your fleet.';return}if(team)state.instructors.push({id:crypto.randomUUID(),name:n,phone:d,specialty:extra,initials:n.split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase()});else state.vehicles.push({id:crypto.randomUUID(),name:n,reg:d.toUpperCase(),transmission:extra});save();$('#modal').close();render();toast(`${team?'Instructor':'Vehicle'} added to the demo.`)}}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));$('#role').onchange=e=>{role=e.target.value;page='overview';render()};$('#reset').onclick=()=>{modal('Reset demo data?',`<p class="sub">This clears changes made in this tab and restores the sample lessons.</p><div class="modal-actions"><button class="secondary" id="keep-data">Keep changes</button><button class="danger" id="reset-data">Reset demo</button></div>`);$('#keep-data').onclick=()=>$('#modal').close();$('#reset-data').onclick=()=>{state=seed();save();$('#modal').close();draft={date:day(1),time:'',instructor:'i1',vehicle:'v1'};instructor='i1';render();toast('Demo reset.')}};document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail));document.querySelectorAll('[data-assess]').forEach(b=>b.onclick=()=>feedback(b.dataset.assess));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});if($('#assigned'))$('#assigned').onchange=e=>{instructor=e.target.value;render()};if(page==='book'){for(const key of ['date','instructor','vehicle'])$('#'+key).onchange=e=>{if(key==='date'&&!e.target.value)return;draft[key]=e.target.value;draft.time='';render()};document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>{draft.time=b.dataset.time;render()});$('#reserve').onclick=()=>{try{const b=reserve(state,draft);save();checkout(b.id)}catch(e){$('#book-error').textContent=e.message}}}if($('#add-resource'))$('#add-resource').onclick=()=>addResource($('#add-resource').dataset.kind);if($('#demo-lesson'))$('#demo-lesson').onclick=()=>{const v=state.vehicles[0],b={id:crypto.randomUUID(),student:'Jerrin',instructor,vehicle:v.id,date:day(-1),time:'14:00',status:'confirmed',amount:800};if(!available(state,b)){toast('A sample lesson already exists at this time. Assess it in the schedule.');return}state.bookings.push(b);state.payments.push({id:crypto.randomUUID(),booking:b.id,amount:800,status:'paid'});save();render();toast('Finished demo lesson added for yesterday. You can assess it now.')}}
render();setInterval(()=>{const before=state.bookings.filter(b=>b.status==='pending').length;expire(state);if(before!==state.bookings.filter(b=>b.status==='pending').length){save();render();toast('An unpaid reservation expired. Its slot is available again.')}},15000);
if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const tool of[{name:'read_demo_bookings',description:'Read the current DriveX review demo bookings. Sample data only.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('No parameters accepted');return{mode:'demo',bookings:list()}}},{name:'open_booking_form',description:'Open the student booking form. Does not reserve a lesson or make a payment.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||Object.keys(input).length)throw Error('No parameters accepted');if(role!=='student')throw Error('Switch to student preview first');navigate('book');return{page:'book',mode:'demo'}}}])try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
